// Auto-generated from src/assets/logo-nobg.png (it) and src/assets/logo.es.png (es)
// — do not edit by hand. To regenerate: re-run the logo build that produced the
// transparent PNGs, then `base64 -w 0 <file>` and replace the strings below.
// The logo is embedded into the report/synastry/transit PDF cover pages by the
// _shared/*-pdf.ts builders. Edge functions cannot read frontend assets at
// runtime, so the bytes ship inside the function bundle. Selection is per
// market so each domain shows its own brand wordmark.
import type { MarketId } from "./markets.ts";

const LOGO_PNG_BASE64_IT = "";

const LOGO_PNG_BASE64_ES = "";

export function decodeLogoPng(market: MarketId = "it"): Uint8Array {
  const b64 = market === "es" ? LOGO_PNG_BASE64_ES : LOGO_PNG_BASE64_IT;
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
